messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
  <title>3D Animation Loop</title>
  <script type="module" src="./three.module.js"></script>
</head>
<body>
  <script>
    import * as THREE from './three.module.js';

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(75, window.innerWidth/window.innerHeight, 0.1, 1000);
    const renderer = new THREE.WebGLRenderer();
    renderer.setSize(window.innerWidth, window.innerHeight);
    document.body.appendChild(renderer.domElement);

    const geometry = new THREE.BoxGeometry(1, 1, 1);
    const materials = [
      new THREE.MeshBasicMaterial({ color: 0xAAAAAA, wireframe: true }),
      new THREE.MeshBasicMaterial({ color: 0xCCCCFF, wireframe: false }),
      new THREE.MeshBasicMaterial({ color: 0xFF00AA, wireframe: false })
    ];

    const anim = new THREE.Animator();
    const walking = new THREE.Mesh();
    const running = new THREE.Mesh();
    const standing = new THREE.Mesh();

    walking.shape = geometry;
    running.shape = geometry;
    standing.shape = geometry;

    walking.material = materials[0];
    running.material = materials[1];
    standing.material = materials[2];

    scene.add(standing);
    scene.add(walking);
    scene.add(running);

    const walkDuration = 2000;
    const runDuration = 3000;
    const standDuration = 2000;

    function animate() {
      animate().add(anim);
      requestAnimationFrame(animate);

      // Limb movement cycles
      if (Math.random() < 0.5) {
        anim.update(walking, running);
      } else {
        anim.update(standing, walking, running);
      }

      // Movement phases
      if (Math.random() < 0.2) {
        walking.material.color.set(0x00FF00);
        running.material.color.set(0xFFFF00);
        standing.material.color.set(0xFF00AA);
        animate();
      } else if (Math.random() < 0.5) {
        walking.material.color.set(0xFF00AA);
        running.material.color.set(0x00FF00);
        standing.material.color.set(0xAAAAAA);
        animate();
      } else {
        walking.material.color.set(0xAAAAAA);
        running.material.color.set(0xAAAAAA);
        standing.material.color.set(0xAAAAAA);
        animate();
      }

      // Update positions
      standing.position.z -= 0.1;
      walking.position.z += 0.1;
      running.position.z -= 0.1;

      scene.render(renderer, camera);
      renderer.update();
    }

    animate();
    window.addEventListener('load', animate);
    window.addEventListener('resize', animate);
  </script>
</body>
</html>
```
